<?php require 'includes/functions.php';$title='Catégories';$base='';$cats=$pdo->query("SELECT c.*,COUNT(p.id) total FROM categories c LEFT JOIN products p ON p.category_id=c.id AND p.status='active' GROUP BY c.id ORDER BY c.name")->fetchAll();require 'includes/header.php';?><section class="banner"><div class="container"><small>FOOTZONE</small><h1>NOS CATÉGORIES</h1></div></section><section class="container section"><div class="cats"><?php foreach($cats as $c):?><a class="cat" href="shop.php?category=<?=(int)$c['id']?>"><b>⚽</b><h3><?=e($c['name'])?></h3><small><?=(int)$c['total']?> produit(s) · Explorer →</small></a><?php endforeach?></div></section><?php require 'includes/footer.php';?>
